#[cfg(test)]mod tests{use super::*;#[test]fn standalone_assets_survive_and_asset_only_changes_are_detected(){let root=std::env::temp_dir().join(uuid::Uuid::new_v4().to_string());let a=root.join("a");let b=root.join("b");fs::create_dir_all(a.join("images")).unwrap();fs::create_dir_all(&b).unwrap();let json=br#"{"rows":[],"image":"images/a.png"}"#;fs::write(a.join("export.json"),json).unwrap();fs::write(a.join("images/a.png"),b"before").unwrap();fs::write(b.join("export.json"),json).unwrap();copy(&a.join("export.json"),&b).unwrap();assert_eq!(manifest(&a.join("export.json")).unwrap(),manifest(&b.join("export.json")).unwrap());fs::write(b.join("images/a.png"),b"after").unwrap();let diff=crate::update_diff::compare_files(&a.join("export.json"),&b.join("export.json")).unwrap();assert!(diff.changed);assert_eq!(diff.other_changes,["Local asset: images/a.png"]);fs::remove_dir_all(root).unwrap();}}
